import{prepare,ready}from'./browser.js';import{owner}from'./commerce.js';
export const initial='00000000-0000-4000-8000-000000000000',second='90000000-0000-4000-8000-000000000001';
export const customers=[{id:'wallet-a',name:'Farmácia A',cnpj:'12345678000199',address:'Rua A, 10, Natal, RN',city:'Natal',houseNumber:'10',state:'RN',priority:2,lat:-5.8,lon:-35.2,locationVerification:'manual_reviewed',locationConfirmedAt:'2026-10-01T12:00:00Z'}];
export async function portfolioSetup(page){await page.clock.setFixedTime(new Date('2026-10-29T15:00:00Z'));await prepare(page,{records:customers,lockAuthFixture:true});await page.addInitScript(({owner,initial,second,customers})=>{
 localStorage.setItem('traxio_sync_owner_v29',owner);window.__portfolioCalls=[];
 const product=(id,name)=>({id,kind:'product',name,priceCents:2000});
 const visit=(id,clientId,name)=>({id,clientId,client:{id:clientId,name},visitDate:'2026-10-29',status:'confirmed',recordedAt:'2026-10-29T12:00:00Z',routeId:'route-'+clientId});
 const other={...customers[0],id:'wallet-b',name:'Farmácia B',address:'Rua B, 99, Recife, PE',houseNumber:'99',city:'Recife',state:'PE',lat:-8.05,lon:-34.9};
 const wrap=(portfolio_id,data,extra={})=>({user_id:owner,portfolio_id,id:data.id,data,revision:1,...extra});
 const seed={rotamapa_portfolios:[{user_id:owner,id:initial,name:'EMS — Natal',revision:1,created_at:'2026-10-01'},{user_id:owner,id:second,name:'Outra marca',revision:1,created_at:'2026-10-02'}],clients:[wrap(initial,customers[0],{local_id:customers[0].id}),wrap(second,other,{local_id:other.id})],traxelo_visit_events:[wrap(initial,visit('40000000-0000-4000-8000-000000000001','wallet-a','Farmácia A'))],rotamapa_commerce_items:[wrap(initial,product('10000000-0000-4000-8000-000000000001','Catálogo A')),wrap(second,product('10000000-0000-4000-8000-000000000002','Catálogo B'))],traxelo_workspace_items:[wrap(initial,{name:'Rota A',points:[customers[0]],start:customers[0]},{id:'80000000-0000-4000-8000-000000000001',kind:'route'}),wrap(second,{name:'Rota B',points:[other],start:other},{id:'80000000-0000-4000-8000-000000000002',kind:'route'})]};
 for(const[t,rows]of Object.entries(seed))if(!localStorage.getItem('__portfolio_cloud:'+t))localStorage.setItem('__portfolio_cloud:'+t,JSON.stringify(rows));
 const original=window.supabase.createClient.bind(window.supabase);window.supabase.createClient=(...args)=>{window.__portfolioHeader=args[2]?.global?.headers?.['x-rotamapa-portfolio']||initial;const c=original(...args),old=c.from.bind(c);c.from=table=>{
  if(!Object.hasOwn(seed,table))return old(table);let mode='read',payload=null,filters=[],offset=0,end=499,ignore=false,single=false;
  const key='__portfolio_cloud:'+table,load=()=>JSON.parse(localStorage.getItem(key)||'[]'),matches=r=>filters.every(([k,v])=>r[k]===v)&&(table==='rotamapa_portfolios'||r.portfolio_id===window.__portfolioHeader);
  const result=()=>{let rows=load(),data;if(mode==='insert'||mode==='upsert'){const previous=rows.find(r=>r.user_id===payload.user_id&&(r.id===payload.id||table==='clients'&&r.local_id===payload.local_id));if(previous){if(!ignore)return{error:{code:'23505',message:'duplicate'}};data=previous;}else{if(table!=='rotamapa_portfolios'&&payload.portfolio_id!==window.__portfolioHeader)return{error:{code:'42501',message:'wrong portfolio'}};data={revision:1,created_at:new Date().toISOString(),...structuredClone(payload)};rows.push(data);}}else if(mode==='update'){const row=rows.find(matches);if(!row)return{data:single?null:[],error:{code:'40001',message:'changed'}};Object.assign(row,structuredClone(payload));data=row;}else data=rows.filter(matches).slice(offset,end+1);
   if(mode!=='read'){localStorage.setItem(key,JSON.stringify(rows));window.__portfolioCalls.push({table,mode,payload:structuredClone(payload)});}return{data:single?(Array.isArray(data)?data[0]||null:data):mode==='update'?[data]:data,count:rows.filter(matches).length,error:null};};
  const q={select:()=>q,eq:(k,v)=>{filters.push([k,v]);return q;},order:()=>q,range:(a,b)=>{offset=a;end=b;return q;},insert:p=>{mode='insert';payload=p;return q;},upsert:(p,o)=>{mode='upsert';payload=p;ignore=o?.ignoreDuplicates;return q;},update:p=>{mode='update';payload=p;return q;},single:()=>{single=true;return Promise.resolve(result());},then:(a,b)=>Promise.resolve(result()).then(a,b)};return q;};return c;};
 },{owner,initial,second,customers});await ready(page);await page.waitForFunction(()=>window.RotaMapaPortfolios?.current()?.name==='EMS — Natal');await expectStores(page);}
export async function expectStores(page){await page.waitForFunction(()=>!!window.RotaMapaSales?.getStore()&&!!window.TraxeloWorkspace?.getStore()&&!!window.TraxeloVisits?.getStore());}
export async function choose(page,id){await page.locator('[data-tab=painel]').click();await page.locator('#choosePortfolio').click();await page.locator('[data-portfolio-id="'+id+'"]').click();await page.waitForFunction(id=>window.RotaMapaPortfolioScope?.loadedId===id,id);await expectStores(page);}
